'use strict';
const $ = (selector, root = document) => root.querySelector(selector);
const app = $('#app');
const dialog = $('#dialog');
const state = {user:null, csrf:'', config:{}, documents:[], archivedCount:0, customerArchivedCount:0, customerSearch:'', customers:[], route:'dashboard', search:'', status:'all', kind:'all', tab:'all', detail:null, messages:[], mailId:null};
const paths = {
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 left:'<path d="M19 12H5m5-5-5 5 5 5"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',
 mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',
 people:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',
 settings:'<path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M5.6 18.4l2.1-2.1M16.3 7.7l2.1-2.1"/><circle cx="12" cy="12" r="5"/>',
 logout:'<path d="M9 4H4v16h5M9 12h12m-4-4 4 4-4 4"/>',
 edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2.8 2.8 0 0 0-4-4L5 15z"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
 refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-2l2 3M4 16l2 3a7 7 0 0 0 12-2"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',
 eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.file}</svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rupiah = n => new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const date = value => new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(new Date(value));
const labels = {pending:'Menunggu nasabah',confirmed:'Nasabah setuju',rejected:'Nasabah menolak'};
const solLabels = {pending:'Menunggu review',approved:'Disetujui SOL',rejected:'Ditolak SOL',revision_requested:'Perlu revisi',cancelled:'Dibatalkan'};
const colors = {pending:'amber',confirmed:'green',rejected:'red',approved:'green',revision_requested:'blue'};
const mailLabels = {queued:'Antrean email',sending:'Sedang dikirim',sent:'Diterima SMTP',local:'Email lokal',retry:'Mencoba ulang',failed:'Email gagal',cancelled:'Dibatalkan'};
const badge = (value, text) => `<span class="badge ${colors[value] || 'grey'}">${esc(text)}</span>`;
function finalStatus(d) {return d.sol_status === 'pending' ? (d.customer_status === 'pending' ? 'pending' : 'review') : d.sol_status;}
function statusBadge(d) {const status = finalStatus(d); return badge(status, status === 'review' ? 'Siap direview' : status === 'pending' ? 'Menunggu nasabah' : solLabels[status]);}
function toast(message, error=false) {const t = $('#toast');t.textContent=message;t.className='visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>{t.className='';},4500);}
async function api(url, data, raw=false) {
 const options={headers:{}};
 if(data!==undefined){options.method='POST';options.headers['Content-Type']='application/json';options.headers['X-CSRF-Token']=state.csrf;options.body=JSON.stringify(data);}
 let res;
 try {res=await fetch('/api'+url,options);} catch {throw new Error('Server tidak dapat dihubungi. Periksa koneksi Anda.');}
 if(!res.ok){const result=await res.json().catch(()=>({}));const error=new Error(result.error||'Permintaan gagal.');error.status=res.status;throw error;}
 return raw?res.blob():res.json();
}
const brand = (light=false) => `<div class="brand"><span class="brand-mark ${light?'light':''}">B</span><div><strong>BPIP</strong><small>DOCUMENT CONFIRMATION</small></div></div>`;
const notice = (message, variant='') => `<div class="notice ${variant}">${icon(variant==='error'?'info':'shield')}<div>${message}</div></div>`;
const empty = (title, subtitle, action='') => `<div class="empty">${icon('file')}<h3>${esc(title)}</h3><p>${esc(subtitle)}</p>${action}</div>`;
const head = (eyebrow,title,subtitle,action='') => `<div class="page-heading spread"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;
function go(route) {if(location.hash==='#'+route) renderRoute();else location.hash=route;}
function errorBlock(err) {return notice(esc(err.message),'error');}
function routeNow() {return location.hash.slice(1)||'dashboard';}
async function boot() {
 try {state.config=await api('/config');}catch(err){app.innerHTML=`<div class="loading-screen">${brand()}${errorBlock(err)}<button class="btn" data-action="reload">Coba lagi</button></div>`;return;}
 if(routeNow().startsWith('confirm/')) return renderPortal();
 try {const session=await api('/session');state.user=session.user;state.csrf=session.csrf;await loadWorkspace();}catch(err){if(err.status===401)renderLogin();else app.innerHTML=`<div class="loading-screen">${brand()}${errorBlock(err)}<button class="btn" data-action="reload">Coba lagi</button></div>`;}
}
function renderLogin() {
 state.user=null;state.csrf='';
 app.innerHTML=`<div class="login-layout"><section class="login-story">${brand(true)}<div class="story-content"><div class="eyebrow">RUANG KERJA OPERASIONAL</div><h1>Setiap persetujuan,<br><em>tercatat dengan jelas.</em></h1><p>Hubungkan petugas, nasabah, dan SOL dalam satu alur konfirmasi dokumen yang teratur.</p><div class="story-flow"><div class="story-step"><span>01</span><div>Ajukan surat<small>Petugas memeriksa detail dan mengirim dokumen.</small></div></div><div class="story-step"><span>02</span><div>Konfirmasi nasabah<small>Persetujuan melalui tautan pribadi di email.</small></div></div><div class="story-step"><span>03</span><div>Review oleh SOL<small>Setujui, tolak, atau kembalikan untuk revisi.</small></div></div></div></div><footer>${icon('shield')} Dua peran. Satu alur. Riwayat lengkap.</footer></section><section class="login-panel"><form id="login-form" class="login-form"><div class="intro"><div class="eyebrow">SELAMAT DATANG KEMBALI</div><h2>Masuk ke ruang kerja</h2><p>Gunakan akun petugas atau SOL Anda.</p></div><div class="field"><label for="login-email">Alamat email</label><input id="login-email" name="email" type="email" autocomplete="username" placeholder="nama@perusahaan.co.id" required></div><div class="field"><label for="login-password">Password</label><input id="login-password" name="password" type="password" autocomplete="current-password" placeholder="Masukkan password" required></div><div id="login-error" class="error-message" role="alert"></div><button class="btn primary full" type="submit">Masuk ke ruang kerja ${icon('arrow')}</button>${state.config.demo?`<div class="demo-box"><strong>Akun demo · pengujian lokal</strong><div class="demo-account"><span>Petugas<br><code>PetugasDemo!2026</code></span><button type="button" class="btn small" data-action="demo" data-role="petugas">Gunakan akun</button></div><div class="demo-account"><span>SOL<br><code>SolDemo!2026</code></span><button type="button" class="btn small" data-action="demo" data-role="sol">Gunakan akun</button></div><small>Email tersimpan di kotak email lokal, belum dikirim ke nasabah.</small></div>`:''}<p class="login-bottom">${icon('lock')} Akses sesuai peran pengguna</p></form></section></div>`;
 $('#login-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button[type=submit]',e.target);button.disabled=true;$('#login-error').textContent='';try{const result=await api('/login',Object.fromEntries(new FormData(e.target)));state.user=result.user;state.csrf=result.csrf;await loadWorkspace();}catch(err){$('#login-error').textContent=err.message;button.disabled=false;}});
}
async function refreshData() {const [docs,customers]=await Promise.all([api('/documents'),api('/customers')]);state.documents=docs.documents;state.archivedCount=docs.archived_count||0;state.customers=customers.customers;state.customerArchivedCount=customers.archived_count||0;updateNavCount();}
function updateNavCount() {const nav=$('.nav [data-route=documents]');if(!nav)return;const count=state.documents.filter(d=>finalStatus(d)===(state.user.role==='sol'?'review':'revision_requested')).length;$('.count',nav)?.remove();if(count){const el=document.createElement('span');el.className='count';el.textContent=count;nav.append(el);}}
async function loadWorkspace() {await refreshData();renderShell();await renderRoute();}
function renderShell() {
 const user=state.user;const isSOL=user.role==='sol';
 const nav=(route,label,ico,count='')=>`<button type="button" data-route="${route}">${icon(ico)}${label}${count?`<span class="count">${count}</span>`:''}</button>`;
 const waiting=state.documents.filter(d=>finalStatus(d)===(isSOL?'review':'revision_requested')).length;
 app.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar">${brand()}<button class="btn text icon mobile-close" data-action="menu" aria-label="Tutup navigasi">${icon('close')}</button><div class="nav-label">RUANG KERJA</div><nav class="nav" aria-label="Navigasi utama">${nav('dashboard','Ringkasan','grid')}${nav('documents',isSOL?'Antrean review':'Pengajuan saya','file',waiting||'')}${isSOL?nav('customers','Data nasabah','people'):nav('initiate','Pengajuan baru','plus')}${state.config.mail_mode==='console'?nav('emails','Kotak email lokal','mail'):''}${nav('settings','Pengaturan akun','settings')}</nav><div class="sidebar-bottom"><div class="workflow-note">${icon('shield')}<strong>Persetujuan berlapis</strong><p>Konfirmasi nasabah dan review SOL tercatat pada setiap versi surat.</p></div><div class="profile"><div class="avatar">${esc(user.name.split(' ').slice(0,2).map(n=>n[0]).join(''))}</div><div><strong>${esc(user.name)}</strong><small>${isSOL?'SOL · Checker':'Petugas · Maker'}</small></div><button class="btn text icon" data-action="logout" title="Keluar dari akun" aria-label="Keluar dari akun">${icon('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="btn text icon mobile-toggle" data-action="menu" aria-label="Buka navigasi">${icon('menu')}</button><span>Ruang kerja</span>${icon('chevron')}<strong id="breadcrumb-page">Ringkasan</strong></div><div class="topbar-right"><span class="date">${new Intl.DateTimeFormat('id-ID',{dateStyle:'long',timeZone:'Asia/Jakarta'}).format(new Date())}</span><span class="role-tag">${isSOL?'SOL / CHECKER':'PETUGAS / MAKER'}</span><button class="btn text icon" data-action="refresh" title="Perbarui data" aria-label="Perbarui data">${icon('refresh')}</button></div></header><main class="main" id="main"></main></div></div>`;
}
async function renderRoute() {
 const route=routeNow();
 if(route.startsWith('confirm/'))return renderPortal();
 if(!state.user)return boot();
 if(!$('#main'))renderShell();
 state.route=route;
 const base=route.split('/')[0];const titles={dashboard:'Ringkasan',documents:state.user.role==='sol'?'Antrean review':'Pengajuan saya',initiate:'Pengajuan baru',customers:'Data nasabah',emails:'Kotak email lokal',settings:'Pengaturan akun',doc:'Detail pengajuan',revise:'Revisi surat'};
 $('#breadcrumb-page').textContent=titles[base]||'Ringkasan';
 document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.route===base||(base==='doc'&&b.dataset.route==='documents')));
 $('#sidebar')?.classList.remove('open');
 const main=$('#main');
 try {
  if(route==='dashboard'||route==='documents')renderDashboard(route==='documents');
  else if(route==='initiate'&&state.user.role==='petugas')renderDocumentForm();
  else if(base==='doc'){main.innerHTML=notice('Memuat detail pengajuan…');const result=await api('/documents/'+encodeURIComponent(route.split('/')[1]));if(state.route!==route)return;state.detail=result.document;renderDetail();}
  else if(base==='revise'&&state.user.role==='petugas'){main.innerHTML=notice('Memuat surat untuk revisi…');const result=await api('/documents/'+encodeURIComponent(route.split('/')[1]));if(state.route!==route)return;state.detail=result.document;renderDocumentForm(result.document);}
  else if(route==='customers'&&state.user.role==='sol')renderCustomers();
  else if(route==='emails'&&state.config.mail_mode==='console'){main.innerHTML=notice('Memuat kotak email lokal…');const result=await api('/outbox');if(state.route!==route)return;state.messages=result.messages;renderEmails();}
  else if(route==='settings')renderSettings();
  else go('dashboard');
 }catch(err){main.innerHTML=errorBlock(err);if(err.status===401)renderLogin();}
}
function renderDashboard(full=false) {
 const sol=state.user.role==='sol';const docs=state.documents;
 const count=status=>docs.filter(d=>finalStatus(d)===status).length;
 const newButton=!sol?`<button class="btn primary" data-route="initiate">${icon('plus')} Pengajuan baru</button>`:full?`<div class="actions">${state.archivedCount?`<button class="btn" data-action="restore-all">Pulihkan pengajuan (${state.archivedCount})</button>`:''}<button class="btn danger" data-action="archive-all" ${docs.length?'':'disabled'}>Hapus semua pengajuan</button></div>`:'';
 const stats=[['Total pengajuan',docs.length,'file','Semua dokumen yang dapat Anda akses'],['Menunggu nasabah',count('pending'),'clock','Menunggu konfirmasi melalui email'],['Siap direview',count('review'),'shield','Nasabah sudah memberikan respons'],['Disetujui SOL',count('approved'),'check','Selesai melewati dua tahap review']];
 const last=docs.slice(0,4);
 $('#main').innerHTML=`${head('DOCUMENT CONFIRMATION',full?(sol?'Antrean review':'Pengajuan saya'):'Ringkasan operasional',full?'Pantau status dan tindak lanjuti setiap pengajuan.':'Seluruh proses konfirmasi dokumen, dalam satu tempat.',newButton)}${!full?`<div class="welcome-banner"><div><div class="eyebrow">${sol?'RUANG REVIEW SOL':'RUANG KERJA PETUGAS'}</div><h2>Selamat datang, ${esc(state.user.name.split(' ')[0])}.</h2><p>${sol?`${count('review')} pengajuan siap Anda periksa. Verifikasi surat dan respons nasabah sebelum memberi keputusan.`:`${count('revision_requested')} pengajuan memerlukan revisi. Pastikan data nasabah dan nominal sesuai sebelum mengirim surat.`}</p></div><div class="banner-seal">${icon('shield')}</div></div><div class="stats">${stats.map(([label,value,ico,foot])=>`<div class="card stat"><div class="stat-label">${label}${icon(ico)}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`).join('')}</div>`:''}<div class="${full?'':'section-layout'}"><section class="card"><div class="card-head"><div><h2>${full?'Daftar pengajuan':'Pengajuan terbaru'}</h2><p>${sol?'Tinjau respons nasabah dan detail surat.':'Status nasabah dan keputusan SOL dipantau terpisah.'}</p></div><span class="muted"><span class="dot"></span> Sinkron setiap 10 detik</span></div>${full?`<div class="card-pad tabs"><button class="tab ${state.tab==='all'?'active':''}" data-tab="all">Semua pengajuan</button><button class="tab ${state.tab==='review'?'active':''}" data-tab="review">Siap direview (${count('review')})</button><button class="tab ${state.tab==='revision_requested'?'active':''}" data-tab="revision_requested">Perlu revisi (${count('revision_requested')})</button></div>`:''}<div class="filters"><div class="search-box">${icon('search')}<input id="search" class="input" aria-label="Cari pengajuan" placeholder="Cari nasabah, CIF, atau ID dokumen…" value="${esc(state.search)}"></div><select id="filter-status" class="input" aria-label="Filter status"><option value="all">Semua status</option><option value="pending">Menunggu nasabah</option><option value="review">Siap direview</option><option value="approved">Disetujui SOL</option><option value="rejected">Ditolak SOL</option><option value="revision_requested">Perlu revisi</option><option value="cancelled">Dibatalkan</option></select><select id="filter-kind" class="input" aria-label="Filter jenis dokumen"><option value="all">Semua jenis</option><option>Standing Instruction</option><option>Warkat</option></select></div><div id="doc-table"></div></section>${!full?`<aside class="dashboard-side stack"><section class="card"><div class="card-head"><div><h3>Perkembangan terakhir</h3><p>Pengajuan yang baru diperbarui</p></div>${icon('clock')}</div><div class="activity-list">${last.length?last.map(d=>`<div class="activity-item"><span class="activity-icon">${icon(finalStatus(d)==='approved'?'check':'file')}</span><div><strong>${esc(d.customer_name)}</strong><p>${esc(finalStatus(d)==='review'?'Menunggu keputusan SOL':finalStatus(d)==='pending'?'Menunggu respons nasabah':solLabels[d.sol_status])}</p><time>${date(d.updated)}</time></div></div>`).join(''):empty('Belum ada aktivitas','Pengajuan baru akan muncul di sini.')}</div></section><div class="side-tip">${icon('info')}<strong>Setiap versi perlu konfirmasi</strong><p>Surat yang direvisi akan dikirim kembali ke nasabah. Tautan versi sebelumnya otomatis dibatalkan.</p></div></aside>`:''}</div><footer class="workspace-footer"><span>BPIP · Document Confirmation Workspace</span><span>${state.config.mail_mode==='console'?'Pengujian lokal · email belum terkirim ke nasabah':'Pengiriman email otomatis via SMTP'}</span></footer>`;
 $('#filter-status').value=state.status;$('#filter-kind').value=state.kind;
 $('#search').addEventListener('input',e=>{state.search=e.target.value;renderTable();});
 $('#filter-status').addEventListener('change',e=>{state.status=e.target.value;renderTable();});
 $('#filter-kind').addEventListener('change',e=>{state.kind=e.target.value;renderTable();});
 renderTable();
}
function renderTable() {
 if(!$('#doc-table'))return;
 let docs=state.documents.filter(d=>(state.status==='all'||finalStatus(d)===state.status)&&(state.kind==='all'||d.kind===state.kind)&&(state.route!=='documents'||state.tab==='all'||finalStatus(d)===state.tab)&&(`${d.customer_name} ${d.id} ${d.cif}`.toLowerCase().includes(state.search.toLowerCase())));
 const total=docs.length;const full=state.route==='documents';if(!full)docs=docs.slice(0,6);
 $('#doc-table').innerHTML=docs.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Nasabah / Dokumen</th><th>Jenis & nominal</th><th>Konfirmasi nasabah</th><th>Status pengajuan</th><th><span class="muted">Detail</span></th></tr></thead><tbody>${docs.map(d=>`<tr><td><strong>${esc(d.customer_name)}</strong><small class="mono">${esc(d.id)} · v${d.version}</small></td><td><strong class="amount">${rupiah(d.nominal)}</strong><small>${esc(d.kind)}</small></td><td>${badge(d.customer_status,labels[d.customer_status])}</td><td>${statusBadge(d)}<small>${mailLabels[d.mail?.status]||'Email belum tersedia'}</small></td><td><button class="btn icon small" data-route="doc/${esc(d.id)}" aria-label="Lihat detail ${esc(d.id)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>Menampilkan ${docs.length} dari ${total} pengajuan</span>${!full?'<a href="#documents">Lihat semua pengajuan →</a>':'<span>Data tersimpan di server</span>'}</div>`:empty(state.documents.length?'Tidak ada pengajuan yang cocok':'Belum ada pengajuan',state.documents.length?'Ubah pencarian atau filter untuk melihat pengajuan lainnya.':state.user.role==='sol'?'Pengajuan dari petugas akan muncul di sini.':'Mulai dengan memilih nasabah dan mengunggah surat.',state.user.role==='petugas'&&!state.documents.length?'<button class="btn primary" data-route="initiate">Buat pengajuan pertama</button>':'');
}
function renderDocumentForm(doc=null) {
 const revision=!!doc;
 if(revision&&doc.sol_status!=='revision_requested'){$('#main').innerHTML=notice('Pengajuan ini belum diminta untuk direvisi.','warn');return;}
 const chosen=revision?(state.customers.find(c=>c.cif===doc.cif)||{cif:doc.cif,name:doc.customer_name,account:doc.account,person:doc.person,email:doc.email}):null;
 $('#main').innerHTML=`${head(revision?'TINDAK LANJUT SOL':'INISIASI DOKUMEN',revision?'Revisi surat':'Pengajuan baru',revision?`${esc(doc.id)} · Surat akan dikirim sebagai versi ${doc.version+1}.`:'Lengkapi detail, unggah surat, lalu kirim konfirmasi kepada nasabah.',`<button class="btn" data-route="${revision?'doc/'+esc(doc.id):'documents'}">${icon('left')} Kembali</button>`)}${revision?`<div class="stack">${notice(`<strong>Catatan SOL</strong><p>${esc(doc.sol_notes)}</p>`,'warn')}<div></div></div>`:''}<div class="form-layout"><form class="card" id="document-form"><section class="form-section"><div class="section-title"><span class="step-number">01</span><div><h3>Data nasabah</h3><p>Pilih CIF nasabah yang telah terdaftar.</p></div></div><div class="field"><label for="customer-search">Nasabah / CIF <span class="required">*</span></label><div class="customer-picker"><div class="search-box">${icon('search')}<input id="customer-search" class="input" type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="customer-options" autocomplete="off" placeholder="Cari dan pilih nama nasabah atau CIF…" value="${chosen?esc(chosen.cif+' · '+chosen.name):''}" ${revision?'readonly':'required'}><input id="customer-select" type="hidden" name="cif" value="${doc?esc(doc.cif):''}"></div><div id="customer-options" class="customer-options" role="listbox" aria-label="Hasil pencarian nasabah" hidden></div></div>${!revision?'<small id="customer-match-count" aria-live="polite">Ketik nama atau CIF, lalu pilih nasabah dari hasil pencarian.</small><small>Nasabah belum terdaftar? Minta SOL menambahkan data nasabah terlebih dahulu.</small>':''}</div><div id="customer-summary"></div></section><section class="form-section"><div class="section-title"><span class="step-number">02</span><div><h3>Detail transaksi</h3><p>Nominal harus sama dengan yang tertera pada surat.</p></div></div><div class="form-grid"><div class="field"><label for="doc-kind">Jenis dokumen <span class="required">*</span></label><select id="doc-kind" name="kind"><option ${doc?.kind==='Standing Instruction'?'selected':''}>Standing Instruction</option><option ${doc?.kind==='Warkat'?'selected':''}>Warkat</option></select></div><div class="field"><label for="doc-nominal">Nominal transaksi (Rp) <span class="required">*</span></label><input id="doc-nominal" name="nominal" type="text" inputmode="numeric" placeholder="Contoh: 250.000.000" value="${doc?new Intl.NumberFormat('id-ID').format(doc.nominal):''}" required><small id="nominal-preview">${doc?rupiah(doc.nominal):'Masukkan nominal dalam Rupiah, tanpa desimal.'}</small></div><div class="field span-2"><label for="doc-description">Keterangan transaksi</label><textarea id="doc-description" name="description" maxlength="1500" placeholder="Tujuan atau keterangan yang perlu diketahui nasabah…">${esc(doc?.description||'')}</textarea></div>${revision?'<div class="field span-2"><label for="revision-notes">Ringkasan perbaikan <span class="required">*</span></label><textarea id="revision-notes" name="notes" maxlength="1500" placeholder="Jelaskan bagian surat yang telah diperbaiki…" required></textarea></div>':''}</div></section><section class="form-section"><div class="section-title"><span class="step-number">03</span><div><h3>${revision?'Unggah surat hasil revisi':'Unggah surat'}</h3><p>Gunakan scan atau dokumen yang terbaca dengan jelas.</p></div></div><div class="upload-area"><div class="upload-icon">${icon('upload')}</div><div class="upload-copy"><h3>${revision?'Pilih surat versi terbaru':'Pilih surat transaksi'}</h3><p>PDF, JPG, atau PNG · Maksimal 5 MB</p></div><button type="button" class="btn primary" data-action="choose-file">${icon('plus')} Pilih surat</button><input type="file" class="visually-hidden" id="doc-file" aria-label="Unggah surat transaksi" aria-required="true" accept=".pdf,.jpg,.jpeg,.png"><div id="file-status" class="file-status" aria-live="polite">Belum ada surat dipilih.</div></div></section><div class="form-bottom"><label class="check"><input type="checkbox" id="doc-ack" required><span>Saya telah memeriksa data nasabah, alamat email, nominal transaksi, dan surat yang akan dikirim.</span></label><div id="form-error" class="error-message" role="alert"></div><div class="form-submit"><small class="muted">${state.config.mail_mode==='console'?'Email tersedia di kotak email lokal.':'Email dikirim otomatis ke nasabah.'}</small><button type="submit" class="btn primary">${icon('mail')} ${revision?'Kirim surat revisi':'Kirim konfirmasi'}</button></div></div></form><aside class="form-side stack"><div class="card"><div class="card-head"><h3>Alur setelah dikirim</h3></div><div class="process-list"><div>${icon('mail')}<div><strong>Email konfirmasi</strong><p>Nasabah menerima tautan pribadi untuk memeriksa surat.</p></div></div><div>${icon('check')}<div><strong>Respons nasabah</strong><p>Setujui atau tolak. Keputusan dicatat untuk versi surat ini.</p></div></div><div>${icon('shield')}<div><strong>Review SOL</strong><p>SOL memeriksa dokumen dan memberikan keputusan akhir.</p></div></div></div></div>${notice('Revisi surat memerlukan konfirmasi baru. Tautan sebelumnya otomatis dibatalkan.')}</aside></div>`;
 const select=$('#customer-select');
 if(!revision)setupCustomerPicker();
 if(chosen)showCustomer(chosen);
 $('#doc-nominal').addEventListener('input',e=>{const digits=e.target.value.replace(/\D/g,'');e.target.value=digits?new Intl.NumberFormat('id-ID').format(Number(digits)):'';$('#nominal-preview').textContent=digits?rupiah(Number(digits)):'Masukkan nominal dalam Rupiah, tanpa desimal.';});
 $('#doc-file').addEventListener('change',e=>{const f=e.target.files[0];const valid=!f||f.size<=5*1024*1024;$('#file-status').textContent=f?(valid?`${f.name} · ${(f.size/1024/1024).toFixed(2)} MB`:'File melebihi batas 5 MB. Pilih surat lain.'):'Belum ada surat dipilih.';e.target.setCustomValidity(valid?'':'File maksimal 5 MB.');$('.upload-area').classList.toggle('has-file',!!f&&valid);$('[data-action="choose-file"]').innerHTML=icon('upload')+(f?' Ganti surat':' Pilih surat');});
 $('#document-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button[type=submit]',e.target);button.disabled=true;$('#form-error').textContent='';try{const file=$('#doc-file').files[0];if(!file||file.size>5*1024*1024)throw new Error('Pilih surat PDF, JPG, atau PNG berukuran maksimal 5 MB.');const nominal=Number($('#doc-nominal').value.replace(/\D/g,''));if(!Number.isSafeInteger(nominal)||nominal<=0)throw new Error('Isi nominal transaksi dengan bilangan bulat positif.');const file64=await fileBase64(file);const payload={cif:doc?.cif||select.value,kind:$('#doc-kind').value,nominal,description:$('#doc-description').value,file:{name:file.name,base64:file64}};if(revision){payload.version=doc.version;payload.notes=$('#revision-notes').value;}showDialog('Periksa sebelum mengirim',`<p>Konfirmasi untuk <strong>${esc(doc?.customer_name||state.customers.find(c=>c.cif===select.value)?.name)}</strong> akan dibuat dengan nominal <strong>${rupiah(nominal)}</strong>.</p><p>${revision?'Nasabah perlu memberikan keputusan baru untuk surat revisi ini.':'Pastikan email penerima dan surat sudah sesuai.'}</p>`,async()=>{button.disabled=true;try{const result=await api(revision?'/documents/'+doc.id+'/revise':'/documents',payload);await refreshData();toast(revision?'Surat revisi masuk antrean email.':'Pengajuan dibuat dan email masuk antrean.');go('doc/'+result.id);}catch(err){$('#form-error').textContent=err.message;button.disabled=false;throw err;}},'Kirim konfirmasi');button.disabled=false;}catch(err){$('#form-error').textContent=err.message;button.disabled=false;}});
}
function setupCustomerPicker() {
 const input=$('#customer-search'), value=$('#customer-select'), list=$('#customer-options');
 let matches=[], active=-1;
 const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1;};
 const highlight=()=>{list.querySelectorAll('[role="option"]').forEach((option,i)=>{option.classList.toggle('highlighted',i===active);option.setAttribute('aria-selected',String(i===active));});if(active>=0){input.setAttribute('aria-activedescendant','customer-option-'+active);list.children[active]?.scrollIntoView({block:'nearest'});}else input.removeAttribute('aria-activedescendant');};
 const render=(query)=>{const q=query.trim().toLocaleLowerCase('id-ID');const all=state.customers.filter(c=>c.name.toLocaleLowerCase('id-ID').includes(q)||c.cif.includes(q));matches=all.slice(0,50);active=-1;list.innerHTML=matches.length?matches.map((c,i)=>`<button type="button" role="option" aria-selected="false" tabindex="-1" id="customer-option-${i}" data-index="${i}"><strong>${esc(c.name)}</strong><span>CIF ${esc(c.cif)}</span></button>`).join(''):'<div class="customer-no-results">Tidak ada nasabah yang cocok.</div>';list.hidden=false;input.setAttribute('aria-expanded','true');input.removeAttribute('aria-activedescendant');$('#customer-match-count').textContent=all.length>50?all.length+' nasabah ditemukan. Ketik lebih spesifik untuk mempersempit hasil.':all.length+' nasabah ditemukan';};
 const choose=(index)=>{const c=matches[index];if(!c)return;value.value=c.cif;input.value=c.cif+' · '+c.name;input.setCustomValidity('');showCustomer(c);$('#customer-match-count').textContent='Nasabah dipilih: '+c.name;close();};
 input.addEventListener('focus',()=>render(value.value?'':input.value));
 input.addEventListener('input',()=>{value.value='';input.setCustomValidity('Pilih nasabah dari hasil pencarian.');showCustomer(null);render(input.value);});
 input.addEventListener('keydown',e=>{if(e.key==='Escape'){close();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden)render(value.value?'':input.value);if(matches.length){active=active<0?(e.key==='ArrowDown'?0:matches.length-1):(active+(e.key==='ArrowDown'?1:-1)+matches.length)%matches.length;highlight();}}else if(e.key==='Enter'&&!list.hidden){e.preventDefault();choose(active<0?0:active);}else if(e.key==='Tab')close();});
 input.addEventListener('blur',close);
 list.addEventListener('pointerdown',e=>{if(e.target.closest('[role="option"]'))e.preventDefault();});
 list.addEventListener('click',e=>{const option=e.target.closest('[data-index]');if(option)choose(Number(option.dataset.index));});
 input.setCustomValidity('Pilih nasabah dari hasil pencarian.');
}
function showCustomer(c) {$('#customer-summary').innerHTML=c?`<div class="customer-summary"><div><label>Nama nasabah</label><strong>${esc(c.name)}</strong></div><div><label>Nomor rekening</label><strong>${esc(c.account)}</strong></div><div><label>Pihak yang berwenang</label><strong>${esc(c.person)}</strong></div><div><label>Email penerima</label><strong>${esc(c.email)}</strong></div></div>`:'';}
function fileBase64(file) {return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('File tidak dapat dibaca.'));reader.readAsDataURL(file);});}
function renderDetail() {
 const d=state.detail;const sol=state.user.role==='sol';const ready=d.sol_status==='pending'&&d.customer_status!=='pending';
 $('#main').innerHTML=`${head('DETAIL PENGAJUAN',esc(d.customer_name),`${esc(d.id)} · Versi ${d.version} · Dibuat ${date(d.created)}`,`<button class="btn" data-route="documents">${icon('left')} Kembali</button>`)}<div class="card status-flow"><div class="status-step">${icon('file')}<strong>01 · Pengajuan petugas</strong>${badge('confirmed','Surat diunggah')}<span class="muted">${esc(d.maker_name)}</span></div><div class="status-step">${icon('mail')}<strong>02 · Konfirmasi nasabah</strong>${badge(d.customer_status,labels[d.customer_status])}<span class="muted">${esc(d.person)}</span></div><div class="status-step">${icon('shield')}<strong>03 · Review SOL</strong>${badge(d.sol_status,solLabels[d.sol_status])}<span class="muted">${d.sol_status==='pending'?'Keputusan akhir pengajuan':'Keputusan tercatat di audit trail'}</span></div></div><br><div class="detail-layout"><div class="stack"><section class="card"><div class="card-head"><h2>Informasi surat</h2>${statusBadge(d)}</div><div class="card-pad"><div class="detail-grid"><div class="span-2"><label>Nominal transaksi</label><strong class="amount">${rupiah(d.nominal)}</strong></div><div><label>Jenis dokumen</label><strong>${esc(d.kind)}</strong></div><div><label>CIF / Nomor rekening</label><strong>${esc(d.cif)} / ${esc(d.account)}</strong></div><div><label>Pihak berwenang</label><strong>${esc(d.person)}</strong></div><div><label>Email konfirmasi</label><strong>${esc(d.email)}</strong></div><div class="span-2"><label>Keterangan</label><strong>${esc(d.description||'Tidak ada keterangan tambahan.')}</strong></div></div><div class="file-card">${icon('file')}<div><strong>${esc(d.file.filename)}</strong><small>Versi ${d.version} · Surat untuk konfirmasi saat ini</small></div><button class="btn small" data-action="preview-file">${icon('eye')} Lihat</button><button class="btn small" data-action="download-file">${icon('download')} Unduh</button></div><div id="preview-container"></div></div></section><section class="card"><div class="card-head"><h2>Audit trail</h2><small class="muted">${d.audit.length} aktivitas</small></div><div class="timeline">${d.audit.map(a=>`<div class="timeline-entry"><strong>${esc(a.action)}</strong>${a.notes?`<p>${esc(a.notes)}</p>`:''}<time>${date(a.at)} · ${esc(a.actor)} · v${a.version}</time>${a.ip?`<p class="mono">IP ${esc(a.ip)}</p>`:''}</div>`).join('')}</div></section></div><aside class="stack"><section class="card review-card"><div class="card-head"><h3>${sol?'Keputusan SOL':'Tindak lanjut petugas'}</h3>${icon('shield')}</div><div class="card-pad stack">${d.sol_notes?notice(`<strong>Catatan SOL</strong><p>${esc(d.sol_notes)}</p>`,d.sol_status==='revision_requested'?'warn':''):''}${sol&&ready?`<p class="muted">Periksa surat dan respons nasabah sebelum memberikan keputusan.</p>${d.customer_status==='rejected'?notice('Nasabah menolak surat. Approval tidak tersedia. Anda dapat menolak pengajuan atau meminta perbaikan.','warn'):''}<div class="field"><label for="sol-notes">Catatan review</label><textarea id="sol-notes" maxlength="1500" placeholder="Wajib untuk penolakan dan permintaan revisi…"></textarea></div><div class="review-actions"><button class="btn primary" data-action="sol-review" data-decision="approved" ${d.customer_status!=='confirmed'?'disabled':''}>${icon('check')} Approval pengajuan</button><button class="btn amber" data-action="sol-review" data-decision="revision_requested">${icon('edit')} Minta revisi surat</button><button class="btn danger" data-action="sol-review" data-decision="rejected">${icon('close')} Tolak pengajuan</button></div>`:sol?notice(d.sol_status==='pending'?'Menunggu respons nasabah. Review tersedia setelah nasabah setuju atau menolak.':'Keputusan SOL sudah tercatat untuk versi surat ini.'):d.sol_status==='revision_requested'?`<p class="muted">Perbaiki surat sesuai catatan SOL, lalu kirim ulang untuk konfirmasi nasabah.</p><button class="btn primary" data-route="revise/${esc(d.id)}">${icon('edit')} Unggah revisi surat</button>`:notice(d.sol_status==='cancelled'?'Pengajuan dibatalkan. Tautan konfirmasi tidak berlaku lagi.':d.customer_status==='pending'?'Email konfirmasi sedang menunggu respons nasabah.':'Respons nasabah sudah tercatat. Pantau hasil review SOL di halaman ini.')}${!sol&&['pending','revision_requested'].includes(d.sol_status)?'<button class="btn danger" data-action="cancel-document">Batalkan pengajuan</button>':''}${sol?'<button class="btn danger" data-action="archive-document">Hapus pengajuan</button>':''}</div></section><section class="card"><div class="card-head"><h3>Pengiriman email</h3>${icon('mail')}</div><div class="card-pad stack"><div><label class="muted">Status email</label><p><strong>${esc(mailLabels[d.mail?.status]||'Belum tersedia')}</strong></p>${d.mail?.sent_at?`<small class="muted">${date(d.mail.sent_at)}</small>`:''}</div>${d.mail?.error?notice(esc(d.mail.error),'error'):''}${d.mail?.status==='local'?notice('Ini email pengujian lokal. Email belum dikirim ke alamat nasabah.','warn'):''}${state.config.mail_mode==='console'?'<button class="btn" data-route="emails">Buka kotak email lokal</button>':''}${!sol&&d.customer_status==='pending'&&d.sol_status==='pending'?'<button class="btn" data-action="resend">'+icon('refresh')+' Kirim tautan baru</button>':''}<small class="muted">${d.sol_status==='cancelled'?'Tautan konfirmasi sudah dinonaktifkan.':`Berlaku hingga ${date(d.file.expires*1000)}. Pengiriman baru membatalkan tautan lama.`}</small></div></section><section class="card"><div class="card-head"><h3>Riwayat versi</h3><small class="muted">${d.versions.length} versi</small></div>${d.versions.map(v=>`<div class="version-row"><span class="step-number">${v.version}</span><div><strong>${esc(v.filename)}</strong><small>${rupiah(v.nominal)}<br>${date(v.created)}</small></div>${v.version===d.version&&d.sol_status!=='cancelled'?'<span class="badge green">Aktif</span>':''}<button class="btn icon small" data-action="download-version" data-version="${v.version}" aria-label="Unduh surat versi ${v.version}">${icon('download')}</button></div>`).join('')}</section></aside></div>`;
}
function renderCustomers() {
 $('#main').innerHTML=`${head('DATA MASTER','Data nasabah','Data penerima konfirmasi digunakan sebagai snapshot pada setiap pengajuan.',`<div class="actions">${state.customerArchivedCount?`<button class="btn" data-action="restore-customers">Pulihkan nasabah (${state.customerArchivedCount})</button>`:''}<button class="btn primary" data-action="new-customer">${icon('plus')} Tambah nasabah</button></div>`)}${notice('Pastikan email benar-benar milik pihak yang berwenang sebelum mengirim konfirmasi.')}<br><section class="card"><div class="card-head"><h2>Nasabah terdaftar</h2><small class="muted" id="customer-list-count"></small></div><div class="filters"><div class="search-box">${icon('search')}<input id="customer-list-search" class="input" type="search" aria-label="Cari nama nasabah atau CIF" placeholder="Cari nama nasabah atau CIF…" value="${esc(state.customerSearch)}"></div></div><div id="customer-table"></div></section>`;
 $('#customer-list-search').addEventListener('input',e=>{state.customerSearch=e.target.value;renderCustomerTable();});
 renderCustomerTable();
}
function renderCustomerTable() {
 const query=state.customerSearch.trim().toLocaleLowerCase('id-ID');const rows=state.customers.filter(c=>c.name.toLocaleLowerCase('id-ID').includes(query)||c.cif.includes(query));
 $('#customer-list-count').textContent=rows.length+' dari '+state.customers.length+' nasabah';
 $('#customer-table').innerHTML=rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>CIF</th><th>Nama nasabah</th><th>Nomor rekening</th><th>Pihak berwenang</th><th>Email</th><th>Aksi</th></tr></thead><tbody>${rows.map(c=>`<tr><td class="mono">${esc(c.cif)}</td><td><strong>${esc(c.name)}</strong></td><td>${esc(c.account)}</td><td>${esc(c.person)}</td><td>${esc(c.email)}</td><td><button class="btn small danger" data-action="archive-customer" data-cif="${esc(c.cif)}" aria-label="Hapus nasabah ${esc(c.name)}">${icon('close')} Hapus</button></td></tr>`).join('')}</tbody></table></div>`:empty(query?'Nasabah tidak ditemukan':'Belum ada nasabah',query?'Coba nama atau CIF yang berbeda.':'Tambahkan nasabah untuk memulai pengajuan.');
}
function newCustomer() {
 if(state.user?.role!=='sol'){toast('Hanya SOL yang dapat menambah nasabah.');return;}
 dialog.innerHTML=`<form id="customer-form"><div class="dialog-head"><h2 id="dialog-title">Tambah nasabah</h2><button type="button" class="btn text icon" data-action="close-dialog" aria-label="Tutup">${icon('close')}</button></div><div class="dialog-body stack"><div class="form-grid"><div class="field"><label for="c-cif">CIF</label><input id="c-cif" name="cif" inputmode="numeric" pattern="[0-9]{3,30}" maxlength="30" required></div><div class="field"><label for="c-account">Nomor Rekening</label><input id="c-account" name="account" type="text" inputmode="numeric" pattern="[0-9]{15}" minlength="15" maxlength="15" title="Nomor rekening tepat 15 digit angka" required></div><div class="field span-2"><label for="c-name">Nama nasabah / perusahaan</label><input id="c-name" name="name" maxlength="250" required></div><div class="field span-2"><label for="c-person">Pihak berwenang</label><input id="c-person" name="person" maxlength="250" required></div><div class="field span-2"><label for="c-email">Alamat email konfirmasi</label><input id="c-email" type="email" name="email" maxlength="254" required></div></div><div id="dialog-error" class="error-message" role="alert"></div></div><div class="dialog-footer"><button type="button" class="btn" data-action="close-dialog">Batal</button><button type="submit" class="btn primary">Simpan nasabah</button></div></form>`;dialog.showModal();
 $('#customer-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button[type=submit]',e.target);button.disabled=true;try{await api('/customers',Object.fromEntries(new FormData(e.target)));await refreshData();dialog.close();renderCustomers();toast('Data nasabah berhasil disimpan.');}catch(err){$('#dialog-error').textContent=err.message;button.disabled=false;}});
}
function renderEmails() {
 if(!state.messages.find(m=>m.id===state.mailId))state.mailId=state.messages[0]?.id;
 const m=state.messages.find(m=>m.id===state.mailId);const link=m?.body.match(/https?:\/\/\S+\/#confirm\/[^\s]+/)?.[0];
 $('#main').innerHTML=`${head('PENGUJIAN ALUR EMAIL','Kotak email lokal','Pratinjau email untuk pengujian, tanpa pengiriman ke alamat nasabah.')}${notice('Mode email lokal aktif. Buka tautan konfirmasi di tab baru untuk menguji respons nasabah. Aktifkan SMTP untuk pengiriman email nyata.','warn')}<br>${m?`<div class="email-grid"><section class="card email-list">${state.messages.map(msg=>`<button class="email-item ${msg.id===m.id?'active':''}" data-mail="${esc(msg.id)}"><strong>${esc(msg.customer_name)}</strong><p>${esc(msg.doc_id)} · v${msg.version}</p><span class="badge grey">${esc(mailLabels[msg.status])}</span></button>`).join('')}</section><section class="card"><div class="card-head"><div><h2>Email konfirmasi</h2><p>${esc(m.recipient)}</p></div><button class="btn small" data-route="doc/${esc(m.doc_id)}">Detail surat</button></div><div class="card-pad stack"><div><strong>${esc(m.subject)}</strong><p class="email-meta">Kepada: ${esc(m.recipient)}<br>Dibuat: ${date(m.created)}</p></div><pre class="email-body">${esc(m.body)}</pre>${link?`<a class="btn primary" href="${esc(link)}" target="_blank" rel="noopener noreferrer">${icon('arrow')} Buka halaman konfirmasi nasabah</a>`:''}</div></section></div>`:empty('Belum ada email','Buat pengajuan terlebih dahulu. Email konfirmasi akan muncul di sini.')}`;
}
function renderSettings() {
 $('#main').innerHTML=`${head('PREFERENSI AKUN','Pengaturan akun','Kelola password akses ruang kerja Anda.')}<div class="form-layout"><section class="card"><div class="card-head"><h2>Ubah password</h2>${icon('lock')}</div><form id="password-form" class="card-pad stack"><div class="field"><label for="old-password">Password saat ini</label><input id="old-password" type="password" name="current" autocomplete="current-password" required></div><div class="field"><label for="new-password">Password baru</label><input id="new-password" type="password" name="password" minlength="12" autocomplete="new-password" required><small>Minimal 12 karakter. Gunakan password unik untuk akun ini.</small></div><div class="field"><label for="repeat-password">Ulangi password baru</label><input id="repeat-password" type="password" minlength="12" autocomplete="new-password" required></div><div id="password-error" class="error-message" role="alert"></div><div><button class="btn primary" type="submit">Simpan password baru</button></div></form></section><section class="card card-pad stack"><div><div class="eyebrow">AKUN ANDA</div><h3>${esc(state.user.name)}</h3><p class="muted">${esc(state.user.email)}</p></div><span class="badge green">${state.user.role==='sol'?'SOL / Checker':'Petugas / Maker'}</span>${notice('Mengubah password akan mengakhiri sesi lain yang menggunakan akun ini.')}</section></div>`;
 $('#password-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button',e.target);button.disabled=true;$('#password-error').textContent='';try{if($('#new-password').value!==$('#repeat-password').value)throw new Error('Password baru dan pengulangan belum sama.');await api('/password',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('Password berhasil diperbarui.');}catch(err){$('#password-error').textContent=err.message;}finally{button.disabled=false;}});
}
function showDialog(title,body,onConfirm,confirmLabel='Ya, lanjutkan',variant='primary') {
 dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="btn text icon" data-action="close-dialog" aria-label="Tutup">${icon('close')}</button></div><div class="dialog-body">${body}<div id="dialog-error" class="error-message" role="alert"></div></div><div class="dialog-footer"><button class="btn" data-action="close-dialog">Batal</button><button class="btn ${variant}" id="dialog-confirm">${esc(confirmLabel)}</button></div>`;
 dialog.showModal();$('#dialog-confirm').addEventListener('click',async()=>{const b=$('#dialog-confirm');b.disabled=true;try{await onConfirm();dialog.close();}catch(err){if($('#dialog-error'))$('#dialog-error').textContent=err.message;b.disabled=false;}});
}
async function review(decision) {
 const d=state.detail;const notes=$('#sol-notes').value.trim();if(decision!=='approved'&&!notes){$('#sol-notes').focus();toast('Isi alasan penolakan atau catatan perbaikan terlebih dahulu.',true);return;}
 const titles={approved:'Approval pengajuan?',rejected:'Tolak pengajuan?',revision_requested:'Minta revisi surat?'};
 showDialog(titles[decision],`<p>${esc(d.id)} · v${d.version}<br><strong>${esc(d.customer_name)} · ${rupiah(d.nominal)}</strong></p><p>${decision==='revision_requested'?'Petugas akan menerima catatan perbaikan. Surat revisi perlu dikonfirmasi ulang oleh nasabah.':'Keputusan akan dicatat dan tidak dapat diubah melalui halaman ini.'}</p>${notes?`<p>Catatan: ${esc(notes)}</p>`:''}`,async()=>{await api('/documents/'+d.id+'/review',{version:d.version,decision,notes});await refreshData();toast('Keputusan SOL berhasil dicatat.');await renderRoute();},decision==='approved'?'Ya, beri approval':decision==='rejected'?'Ya, tolak':'Kirim permintaan revisi',decision==='rejected'?'danger':decision==='revision_requested'?'amber':'primary');
}
let previewUrl=null;
async function viewFile(download=false,portalToken=null) {
 if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}
 const blob=portalToken?await api('/portal/file',{token:portalToken},true):await api('/documents/'+state.detail.id+'/file',undefined,true);
 previewUrl=URL.createObjectURL(blob);
 if(download){const a=document.createElement('a');a.href=previewUrl;a.download=portalToken?state.portal.file.filename:state.detail.file.filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);}
 else{const mime=portalToken?state.portal.file.mime:state.detail.file.mime;$('#preview-container').innerHTML=mime==='application/pdf'?`<iframe class="file-preview" title="Pratinjau surat PDF" src="${previewUrl}"></iframe>`:`<img class="image-preview" alt="Pratinjau surat" src="${previewUrl}">`;}
}
async function renderPortal() {
 const token=routeNow().slice('confirm/'.length);state.route=routeNow();
 app.innerHTML=`<main class="portal"><div class="portal-header">${brand()}${badge('confirmed','Konfirmasi pribadi')}</div><div class="card card-pad">Memuat surat Anda…</div></main>`;
 try{const result=await api('/portal',{token});if(routeNow()!=='confirm/'+token)return;state.portal=result;state.portalToken=token;renderPortalForm();}catch(err){app.innerHTML=`<main class="portal"><div class="portal-header">${brand()}</div><section class="card result-card"><div class="success-icon">${icon('lock')}</div><h1>Tautan tidak tersedia</h1><p>${esc(err.message)}</p>${notice('Jika Anda membutuhkan surat atau tautan baru, silakan hubungi petugas yang mengirim email konfirmasi.','warn')}</section></main>`;}
}
function renderPortalForm() {
 const {document:d,file,expires}=state.portal;
 app.innerHTML=`<main class="portal"><header class="portal-header">${brand()}${badge('confirmed','Konfirmasi pribadi')}</header><div class="portal-intro"><div class="eyebrow">KONFIRMASI DOKUMEN</div><h1>Periksa surat Anda.</h1><p>Yth. ${esc(d.person)}, mohon pastikan detail di bawah sesuai dengan surat yang Anda ajukan.</p></div><section class="card"><div class="card-pad"><div class="portal-amount"><small>NOMINAL TRANSAKSI</small><strong>${rupiah(d.nominal)}</strong><p>${esc(d.kind)}</p></div><div class="detail-grid"><div><label>Nama nasabah</label><strong>${esc(d.customer_name)}</strong></div><div><label>Pihak berwenang</label><strong>${esc(d.person)}</strong></div><div><label>ID dokumen</label><strong class="mono">${esc(d.id)}</strong></div><div><label>Versi surat</label><strong>Versi ${d.version}</strong></div><div class="span-2"><label>Keterangan transaksi</label><strong>${esc(d.description||'Tidak ada keterangan tambahan.')}</strong></div></div><div class="file-card">${icon('file')}<div><strong>${esc(file.filename)}</strong><small>Surat yang dimintakan konfirmasi</small></div><button class="btn small" data-action="portal-preview">${icon('eye')} Lihat</button><button class="btn small" data-action="portal-download">${icon('download')} Unduh</button></div><div id="preview-container"></div></div><form class="form-section stack" id="portal-form"><div class="field"><label for="portal-notes">Catatan / alasan penolakan</label><textarea id="portal-notes" maxlength="1500" placeholder="Wajib jika Anda menolak surat. Jelaskan detail yang belum sesuai…"></textarea></div><label class="check"><input type="checkbox" id="portal-ack" required><span>Saya adalah pihak yang berwenang. Saya telah memeriksa surat versi ${d.version}, detail transaksi, dan nominal <strong>${rupiah(d.nominal)}</strong>.</span></label><div id="portal-error" class="error-message" role="alert"></div><div class="actions"><button type="submit" class="btn danger" name="decision" value="rejected">${icon('close')} Tolak surat</button><button type="submit" class="btn primary" name="decision" value="confirmed">${icon('check')} Setujui surat</button></div>${notice('Keputusan Anda hanya dapat dicatat satu kali untuk surat ini. Setelah Anda setuju, pengajuan akan diperiksa oleh SOL.')}</form></section><footer class="portal-footer"><p>${icon('lock')} Tautan pribadi · Jangan bagikan kepada pihak lain</p><p>Berlaku sampai ${date(expires*1000)} WIB</p><p>${esc(state.config.bank_name||'BPIP Document Confirmation')}</p></footer></main>`;
 $('#portal-form').addEventListener('submit',e=>{e.preventDefault();const decision=e.submitter?.value;if(!decision)return;const notes=$('#portal-notes').value.trim();$('#portal-error').textContent='';if(decision==='rejected'&&!notes){$('#portal-error').textContent='Tuliskan alasan penolakan agar petugas dapat menindaklanjuti.';$('#portal-notes').focus();return;}
 showDialog(decision==='confirmed'?'Setujui surat ini?':'Tolak surat ini?',`<p>${esc(d.id)} · Versi ${d.version}<br><strong>${rupiah(d.nominal)}</strong></p><p>${decision==='confirmed'?'Anda menyatakan bahwa surat dan nominal transaksi sudah sesuai.':'Penolakan dan alasan Anda akan diteruskan kepada petugas dan SOL.'}</p>`,async()=>{await api('/portal/decision',{token:state.portalToken,decision,notes,acknowledged:$('#portal-ack').checked});renderPortalResult(decision,d);},decision==='confirmed'?'Ya, setujui surat':'Ya, tolak surat',decision==='confirmed'?'primary':'danger');
 });
}
function renderPortalResult(decision,d) {
 app.innerHTML=`<main class="portal"><header class="portal-header">${brand()}</header><section class="card result-card"><div class="success-icon">${icon(decision==='confirmed'?'check':'file')}</div><div class="eyebrow">RESPONS BERHASIL DICATAT</div><h1>${decision==='confirmed'?'Terima kasih atas konfirmasi Anda.':'Penolakan Anda telah kami terima.'}</h1><p>${esc(d.id)} · Versi ${d.version}<br><strong>${rupiah(d.nominal)}</strong></p><p>${decision==='confirmed'?'Persetujuan surat Anda telah diteruskan kepada SOL untuk diperiksa.':'Petugas dan SOL dapat melihat penolakan beserta catatan Anda untuk ditindaklanjuti.'}</p>${notice('Tautan ini telah digunakan. Anda dapat menutup halaman ini.')}</section><footer class="portal-footer">${esc(state.config.bank_name)}</footer></main>`;
}
async function handleAction(e) {
 const target=e.target.closest('[data-route],[data-action],[data-tab],[data-mail]');if(!target)return;
 if(target.dataset.route){go(target.dataset.route);return;}
 if(target.dataset.tab){state.tab=target.dataset.tab;renderDashboard(true);return;}
 if(target.dataset.mail){state.mailId=target.dataset.mail;renderEmails();return;}
 const action=target.dataset.action;
 try{
 if(action==='demo'){$('#login-email').value=target.dataset.role+'@bpip.local';$('#login-password').value=target.dataset.role==='petugas'?'PetugasDemo!2026':'SolDemo!2026';}
 else if(action==='reload')location.reload();
 else if(action==='menu')$('#sidebar').classList.toggle('open');
 else if(action==='close-dialog')dialog.close();
 else if(action==='new-customer')newCustomer();
 else if(action==='choose-file')$('#doc-file').click();
 else if(action==='archive-customer'){const c=state.customers.find(c=>c.cif===target.dataset.cif);if(!c)return;showDialog('Hapus nasabah?',`<p><strong>${esc(c.name)}</strong> · CIF ${esc(c.cif)} akan disembunyikan dari data nasabah dan pilihan pengajuan baru. Surat dan riwayat pengajuan lama tetap tersedia. SOL dapat memulihkan nasabah ini.</p>`,async()=>{await api('/customers/'+encodeURIComponent(c.cif)+'/archive',{});await refreshData();renderCustomers();toast('Nasabah dihapus dari daftar.');},'Hapus nasabah','danger');}
 else if(action==='restore-customers'){showDialog('Pulihkan nasabah?','<p>Semua nasabah yang dihapus akan kembali tersedia untuk pengajuan baru.</p>',async()=>{await api('/customers/restore-all',{});await refreshData();renderCustomers();toast('Data nasabah dipulihkan.');},'Pulihkan nasabah');}
 else if(action==='logout'){showDialog('Keluar dari ruang kerja?','<p>Anda dapat masuk kembali menggunakan akun yang sama.</p>',async()=>{await api('/logout',{});state.documents=[];state.customers=[];state.detail=null;renderLogin();},'Keluar');}
 else if(action==='refresh'){target.disabled=true;await refreshData();await renderRoute();toast('Data sudah diperbarui.');target.disabled=false;}
 else if(action==='sol-review')review(target.dataset.decision);
 else if(action==='download-version'){target.disabled=true;const blob=await api('/documents/'+state.detail.id+'/versions/'+target.dataset.version+'/file',undefined,true);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=state.detail.versions.find(v=>String(v.version)===target.dataset.version).filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);target.disabled=false;}
 else if(action==='preview-file'||action==='download-file'){target.disabled=true;await viewFile(action==='download-file');target.disabled=false;}
 else if(action==='portal-preview'||action==='portal-download'){target.disabled=true;await viewFile(action==='portal-download',state.portalToken);target.disabled=false;}
 else if(action==='archive-document'){const d=state.detail;showDialog('Hapus pengajuan dari daftar?',`<p>${esc(d.id)} akan dipindahkan ke arsip. Surat dan riwayat tetap tersimpan dan dapat dipulihkan oleh SOL. Tautan nasabah dinonaktifkan; email yang sudah terkirim tidak dapat ditarik kembali.</p>`,async()=>{await api('/documents/'+d.id+'/archive',{version:d.version});await refreshData();go('documents');toast('Pengajuan dihapus dari daftar.');},'Hapus pengajuan','danger');}
 else if(action==='archive-all'){const ids=state.documents.map(d=>d.id);showDialog('Hapus semua pengajuan?',`<p>Semua <strong>${ids.length} pengajuan</strong> akan dihapus dari daftar petugas dan SOL, termasuk yang sudah selesai. Data nasabah dan akun tetap tersedia. Surat serta audit disimpan di arsip dan bisa dipulihkan. Tautan konfirmasi dinonaktifkan.</p>`,async()=>{await api('/documents/archive-all',{ids});await refreshData();renderDashboard(true);toast('Semua pengajuan dihapus dari daftar.');},'Hapus semua pengajuan','danger');}
 else if(action==='restore-all'){showDialog('Pulihkan pengajuan?', '<p>Semua pengajuan di arsip akan kembali muncul. Tautan konfirmasi lama tetap tidak berlaku. Petugas dapat meminta tautan baru untuk pengajuan yang masih menunggu nasabah.</p>',async()=>{await api('/documents/restore-all',{});await refreshData();renderDashboard(true);toast('Pengajuan dipulihkan.');},'Pulihkan pengajuan');}
 else if(action==='cancel-document'){const d=state.detail;showDialog('Batalkan pengajuan?', '<p>Riwayat dan surat tetap tersimpan. Tautan konfirmasi dinonaktifkan. Email yang sudah terkirim tidak dapat ditarik kembali.</p><div class="field"><label for="cancel-notes">Alasan pembatalan</label><textarea id="cancel-notes" maxlength="1500" required></textarea></div>',async()=>{const notes=$('#cancel-notes').value.trim();if(!notes)throw new Error('Isi alasan pembatalan.');await api('/documents/'+d.id+'/cancel',{version:d.version,notes});await refreshData();await renderRoute();toast('Pengajuan dibatalkan.');},'Batalkan pengajuan');}
 else if(action==='resend'){const d=state.detail;showDialog('Kirim tautan konfirmasi baru?','<p>Tautan sebelumnya akan dibatalkan. Nasabah akan menerima email baru untuk surat yang sama.</p>',async()=>{await api('/documents/'+d.id+'/resend',{version:d.version});await refreshData();await renderRoute();toast('Email baru masuk antrean.');},'Kirim email baru');}
 }catch(err){target.disabled=false;toast(err.message,true);if(err.status===401&&!state.route.startsWith('confirm/'))renderLogin();}
}
app.addEventListener('click',handleAction);dialog.addEventListener('click',handleAction);
window.addEventListener('hashchange',()=>{if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}renderRoute();});
setInterval(async()=>{if(!state.user||state.route.startsWith('confirm/')||dialog.open)return;try{await refreshData();if(['dashboard','documents'].includes(state.route)){renderTable();if(state.route==='dashboard'){const stats=document.querySelectorAll('.stat-value');const count=s=>state.documents.filter(d=>finalStatus(d)===s).length;[state.documents.length,count('pending'),count('review'),count('approved')].forEach((v,i)=>{if(stats[i])stats[i].textContent=v;});}}else if(state.route.startsWith('doc/')&&!$('#sol-notes')?.value){const result=await api('/documents/'+state.detail.id);if(result.document.updated!==state.detail.updated||result.document.mail?.status!==state.detail.mail?.status){state.detail=result.document;renderDetail();}}}catch(err){if(err.status===401)renderLogin();}},10000);
boot();
